// Test-only stand-in for expo-sqlite. Implements exactly the async surface db.js and
// finance/calculator.js actually call (execAsync, getAllAsync, getFirstAsync, runAsync),
// backed by Node's built-in node:sqlite so the real db.js/finance/calculator.js modules
// run unmodified against a real SQLite engine in plain Node. NOT used by the actual Expo
// app; only by the automated test suite.
import { DatabaseSync } from 'node:sqlite';

export async function openDatabaseAsync(name) {
  const raw = new DatabaseSync(':memory:');
  return {
    async execAsync(sql) { raw.exec(sql); },
    async getAllAsync(sql, ...params) { return raw.prepare(sql).all(...params); },
    async getFirstAsync(sql, ...params) {
      const row = raw.prepare(sql).get(...params);
      return row === undefined ? null : row;
    },
    async runAsync(sql, ...params) {
      const info = raw.prepare(sql).run(...params);
      return { lastInsertRowId: info.lastInsertRowid, changes: info.changes };
    },
  };
}
